import express from "express";
import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY || "" });

const app = express();
const PORT = process.env.PORT || 3000;

// CORS - allow all origins
app.use((req, res, next) => {
  res.setHeader("Access-Control-Allow-Origin", "*");
  res.setHeader("Access-Control-Allow-Methods", "GET, POST, OPTIONS");
  res.setHeader("Access-Control-Allow-Headers", "Content-Type, Authorization");
  if (req.method === "OPTIONS") return res.status(200).end();
  next();
});

app.use(express.json({ limit: "20mb" }));

// Health check
app.get("/", (req, res) => {
  res.json({ status: "CoinVault API running", version: "1.0.0" });
});

// Scan endpoint - Gemini Vision
app.post("/api/scan", async (req, res) => {
  try {
    const { image } = req.body;
    if (!image) return res.status(400).json({ status: "error", message: "No image provided" });

    if (!process.env.GEMINI_API_KEY) {
      return res.json({
        status: "success",
        data: {
          id: `SCA_${Math.floor(Math.random() * 9000) + 1000}`,
          type: "coin", name: "1909-S VDB Lincoln Cent",
          value: "$1,350.00", grade: "MS-65", trend: "+8.3%",
          confidence: 94, image: "",
          mintLocation: "San Francisco Mint (S)", composition: "95% Copper, 5% Tin/Zinc",
          conditionScale: "Gem Uncirculated", surfaceScore: "9.2/10",
          scarcityRank: "Extremely Rare", detailImages: [],
          conditionBreakdown: { luster: 9.5, strike: 9.0, eyeAppeal: 9.2 }, comparisons: []
        }
      });
    }

    const response = await ai.models.generateContent({
      model: "gemini-2.0-flash",
      contents: [{
        role: "user",
        parts: [
          { inlineData: { mimeType: "image/jpeg", data: image } },
          { text: "You are an expert numismatist. Analyze this coin or banknote. Return ONLY raw JSON: {id, type, name, value, grade, trend, confidence, image, mintLocation, composition, conditionScale, surfaceScore, scarcityRank, detailImages, conditionBreakdown, comparisons}" }
        ]
      }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            type: { type: Type.STRING },
            name: { type: Type.STRING },
            value: { type: Type.STRING },
            grade: { type: Type.STRING },
            trend: { type: Type.STRING },
            confidence: { type: Type.NUMBER },
            mintLocation: { type: Type.STRING },
            composition: { type: Type.STRING },
            conditionScale: { type: Type.STRING },
            surfaceScore: { type: Type.STRING },
            scarcityRank: { type: Type.STRING },
          }
        }
      }
    });

    const text = response.candidates?.[0]?.content?.parts?.[0]?.text || "{}";
    const parsed = JSON.parse(text.replace(/```json|```/g, "").trim());

    res.json({
      status: "success",
      data: {
        id: `SCA_${Math.floor(Math.random() * 9000) + 1000}`,
        image: "", detailImages: [],
        conditionBreakdown: { luster: 8.5, strike: 8.5, eyeAppeal: 8.5 },
        comparisons: [],
        ...parsed
      }
    });
  } catch (error) {
    console.error("Scan error:", error);
    res.status(500).json({ status: "error", message: String(error) });
  }
});

// Valuation trends
app.post("/api/valuation/trends", async (req, res) => {
  try {
    const { itemName } = req.body;
    const mockTrends = Array.from({ length: 12 }, (_, i) => ({
      month: new Date(2025, i, 1).toLocaleString("default", { month: "short" }),
      value: Math.floor(800 + Math.random() * 600)
    }));
    res.json({ status: "success", data: { trends: mockTrends } });
  } catch (error) {
    res.status(500).json({ status: "error", message: String(error) });
  }
});

// Valuation mock
app.post("/api/valuation", (req, res) => {
  res.json({ status: "success", data: { value: "$1,250.00", grade: "MS-64", confidence: 89 } });
});

// Register device
app.post("/api/register-device", (req, res) => {
  console.log("Device registered:", req.body.token);
  res.json({ status: "success" });
});

app.listen(PORT, () => console.log(`CoinVault API running on port ${PORT}`));
